          switcher: {
            label: "Switch environment",
            options: environments,
            value: environment,
            onChange: setEnvironment
          }
        }
      ]}
      notifications={{ unread: 2 }}
      search={{ onClick: () => {} }}
      account={{
        name: "Sarah Lin",
